-- Original Italian translations for 62 missing Zephras IDs.
-- Fingerprints checked against each English variant. No local unguarded overrides.
local db = WoWForeverIT_QuestIT.DataIT
db[92466] = db[92466] or {}
db[92466]["title"] = db[92466]["title"] or {it = "La chiamata della terra", enHash = {"e9b66c43"}}
db[92466] = db[92466] or {}
db[92466]["text"] = db[92466]["text"] or {it = "Sebbene dobbiamo gran parte della nostra prosperità al vento, il cammino che seguiamo ci impone di rispondere alla chiamata di tutti e quattro gli elementi primari e affrontare una prova per ciascuno. Prima di iniziare davvero la tua prima prova, però, devi dimostrare la forza della tua determinazione.\n\nRaggiungi le pietre erette a est. Vi è stato avvistato un gruppo di convertiti Al'Aketh: devono essere scacciati. Affronta i cultisti e portami uno dei loro sigilli come prova delle tue imprese.", enHash = {"e34e809d","24ea3a6b","d514b915"}}
db[92466] = db[92466] or {}
db[92466]["objectives"] = db[92466]["objectives"] or {it = "Porta un Sigillo di Akir al Plasmavento Boro.", enHash = {"f1fbf597"}}
db[92466] = db[92466] or {}
db[92466]["progress"] = db[92466]["progress"] or {it = "Il culto Al’Aketh rappresenta il pericolo più diretto e urgente per la nostra terra. Le loro azioni sempre più estremiste hanno destabilizzato la società e danneggiato il nostro legame già fragile con gli spiriti dei quattro venti. Gli elementi esigono che dimostriamo resistenza e determinazione, qualità proprie della terra.", enHash = {"28d35af9"}}
db[92467] = db[92467] or {}
db[92467]["title"] = db[92467]["title"] or {it = "La chiamata della terra", enHash = {"e9b66c43"}}
db[92467] = db[92467] or {}
db[92467]["text"] = db[92467]["text"] or {it = "La sapta è una bevanda creata per legare i nostri spiriti agli elementi. Infusa di magia, permette a chi possiede una volontà salda di vedere gli elementi come nessun altro può fare. Il tuo spirito si legherà all’elemento per cui è stata preparata, e solo pochi sciamani ne conoscono la ricetta.\n\nLa sapta va bevuta sempre in un luogo sacro, mai altrove: ricordalo.\n\nCerca l’Altura degli Spiriti, oltre il passo a nord-est. Bevi lì la tua sapta e... beh, vedrai ciò che devi vedere.", enHash = {"9e6b4094","01f74dbe","1877077e"}}
db[92467] = db[92467] or {}
db[92467]["objectives"] = db[92467]["objectives"] or {it = "Trova l’Altura degli Spiriti e bevi la Sapta della Terra.", enHash = {"754aca7b"}}
db[92467] = db[92467] or {}
db[92467]["reward"] = db[92467]["reward"] or {it = "Ah... $N... figlio dei quattro venti... Cerchi comprensione. Cerchi risposte. Perché i venti vi hanno abbandonati? Come potete farli tornare? Non posso rispondere: non conosco i motivi né i movimenti dei venti.\n\nPosso però insegnarti molto della terra, della sua forza e determinazione. Anche quassù, in questo mare infinito di nuvole, sei una creatura della terra. Se speri di trovare la forza per parlare ancora agli spiriti dei quattro venti, questo è il cammino che devi percorrere.", enHash = {"bf027c9e","328ecf9c","599dfbc6"}}
db[92468] = db[92468] or {}
db[92468]["title"] = db[92468]["title"] or {it = "La chiamata della terra", enHash = {"e9b66c43"}}
db[92468] = db[92468] or {}
db[92468]["text"] = db[92468]["text"] or {it = "Prendi questo Quarzo Grezzo e portalo a colui che chiami Plasmavento Boro come prova del nostro incontro. Creerà un totem per te, e questo frammento ne sarà il cuore. Per quanto piccolo possa sembrare, scoprirai che le dimensioni non contano e che persino le cose più minute possono durare più di molte altre.\n\nAbbi pazienza, $N. Mantieni la tua forza. Cerca la saggezza. Questo è ciò che gli elementi ti chiedono. Alla fine diverrai tutt’uno con la terra: rispettala ed essa rispetterà te.", enHash = {"2df64a37","7fd78f39","2917b3cf"}}
db[92468] = db[92468] or {}
db[92468]["objectives"] = db[92468]["objectives"] or {it = "Porta il Quarzo Grezzo al Plasmavento Boros nel Bosco di Thendal.", enHash = {"e3d9d22a"}}
db[92468] = db[92468] or {}
db[92468]["progress"] = db[92468]["progress"] or {it = "Scoprirai che il nostro cammino non è semplice come sembra. Cerchiamo la voce per parlare agli spiriti del vento, ma il vento è soltanto una delle forze elementali del mondo. Solo comprendendo e, speriamo, padroneggiando tutti e quattro gli elementi potremo ritrovare la voce e cantare ancora i canti del vento.", enHash = {"29663892"}}
db[92468] = db[92468] or {}
db[92468]["reward"] = db[92468]["reward"] or {it = "Bene!\n\nIl totem che creerò per te è più di un simbolo del tuo rango tra i $C: possiede anche altri poteri. Può servire da punto focale per gli incantesimi legati alla terra. Man mano che acquisirai saggezza, potrai accedere a nuovi poteri della terra.\n\nGli istruttori sapranno quando avrai raggiunto la preparazione necessaria.\n\nPer ora, prendi questo totem della terra...", enHash = {"725b5ba9","3cf1b00d","772be677"}}
db[92528] = db[92528] or {}
db[92528]["title"] = db[92528]["title"] or {it = "Tra i fedeli", enHash = {"fa61b5ee"}}
db[92528] = db[92528] or {}
db[92528]["text"] = db[92528]["text"] or {it = "I fedeli di Al'Akir diventano sempre più forti grazie a ogni nuova recluta entusiasta come te. Come puoi vedere, la nostra forza dà forma alla tempesta stessa!\n\nNormalmente ti manderei subito dal Sacerdote del Cielo Aanders per una valutazione, ma al momento sta ricevendo un ospite nella locanda a nord del villaggio. Per ora evita quel posto. Una recluta trasandata come te sarebbe fuori luogo in presenza di un ospite simile.\n\nIntanto, cerca soltanto di non intralciare nessuno.", enHash = {"4aa2d15e","7993a3f8","4f6badb8"}}
db[92528] = db[92528] or {}
db[92528]["objectives"] = db[92528]["objectives"] or {it = "Esplora il villaggio di Falaath per scoprire le intenzioni del culto nelle alture di Shen'dar.", enHash = {"69b66193"}}
db[92528] = db[92528] or {}
db[92528]["progress"] = db[92528]["progress"] or {it = "Cosa hai scoperto?", enHash = {"b8d198b9"}}
db[92528] = db[92528] or {}
db[92528]["reward"] = db[92528]["reward"] or {it = "C’era Lorthuna in persona? È lei a guidare tutto quel maledetto culto!\n\nSe vogliono attaccare Shen’dar e la torre occidentale, dobbiamo prepararci. Ma perché la torre? Il villaggio lo capisco, ma la torre non ha grande importanza strategica, oltre a essere un piccolo punto di vedetta.\n\nComunque saremo pronti. Scopriranno che la gente delle alture non è così facile da cogliere di sorpresa.", enHash = {"cc15d0d9","6928182f","e0f0de85"}}
db[92529] = db[92529] or {}
db[92529]["title"] = db[92529]["title"] or {it = "Il villaggio di Falaath", enHash = {"5b5e78b1"}}
db[92529] = db[92529] or {}
db[92529]["text"] = db[92529]["text"] or {it = "Mi rallegra sapere che desideri servire Al'Akir. Le difficoltà che il nostro popolo affronta nascono dalla nostra stessa indolenza. Siamo diventati superbi e abbiamo dato per scontata la generosità dei venti. Il ristagno che ne è seguito ha spinto gli spiriti del vento ad abbandonarci.\n\nSolo attraverso atti di contrizione potremo sentire ancora la carezza del vento. Se cerchi la compagnia di shen'dorei che condividano le tue idee, raggiungi il villaggio di Falaath e trova il Missionario Jasaan. Ti marchierò affinché i fedeli ti riconoscano come recluta.", enHash = {"f9551a13","3ff08723","74f0b64d"}}
db[92529] = db[92529] or {}
db[92529]["objectives"] = db[92529]["objectives"] or {it = "Presentati al Missionario Jasaan presso l’ingresso del villaggio di Falaath.\n\nSe perdi il Marchio di Akir, parla con Sania Silverstream nel villaggio di Shen'dar per riottenere l’effetto.", enHash = {"2a783072","d4a56904","9f72f89a"}}
db[92529] = db[92529] or {}
db[92529]["reward"] = db[92529]["reward"] or {it = "Che cosa vedo? Una nuova recluta inviata da sorella Sania per servire il Signore del Vento? Oggi siamo davvero benedetti dal tocco dei quattro venti!\n\nAccogliamo tutti coloro che desiderano godere delle benedizioni di Al’Akir.", enHash = {"4fcef9a5","e454ff2f","ea70ca45"}}
db[92550] = db[92550] or {}
db[92550]["title"] = db[92550]["title"] or {it = "Caos nelle alture", enHash = {"2691e5eb"}}
db[92550] = db[92550] or {}
db[92550]["text"] = db[92550]["text"] or {it = "La nostra difesa migliore potrebbe essere un attacco deciso. Il vantaggio è che sappiamo che stanno per attaccare. Non si aspetteranno che li colpiamo per primi.\n\nTi ho già chiesto molto, ma torna al villaggio di Falaath. Uccidi quanti più cultisti puoi e, se riesci ad avvicinarti, uccidi il comandante e portami la sua testa. Io resterò qui a organizzare i cittadini e i nostri pochi guardiani per prepararci a difenderci... nel caso tu non tornassi.", enHash = {"6353cd28","220b45e4","06cf4a0e"}}
db[92550] = db[92550] or {}
db[92550]["objectives"] = db[92550]["objectives"] or {it = "Raggiungi le rovine del villaggio di Falaath, uccidi 6 Invocatori della Tempesta Al'Aketh e 4 Fulmini Viventi e recupera la testa del Comandante Cyclas.", enHash = {"a8fb9b69"}}
db[92550] = db[92550] or {}
db[92550]["progress"] = db[92550]["progress"] or {it = "È bello ribaltare la situazione contro questi fanatici.", enHash = {"8d9185a1"}}
db[92551] = db[92551] or {}
db[92551]["title"] = db[92551]["title"] or {it = "Provviste rubate", enHash = {"3b04a8a6"}}
db[92551] = db[92551] or {}
db[92551]["text"] = db[92551]["text"] or {it = "Ho sentito che potresti andare al villaggio di Falaath. Mentre sei lì, cerca le nostre scorte rubate.\n\nDa mesi gli Al'Aketh assaltano le carovane che trasportano merci, come cibo e pietre del vento, da e verso le pianure. Ovviamente danno la colpa ai banditi, ma sappiamo tutti dove finisce quella roba. Se a Falaath è rimasto qualcosa, recuperarlo ci sarebbe di enorme aiuto.", enHash = {"2ab3f00d","f94139af","5c94fd59"}}
db[92551] = db[92551] or {}
db[92551]["objectives"] = db[92551]["objectives"] or {it = "Raccogli 10 pacchi di Provviste Rubate di Shen'dar nel villaggio di Falaath, nelle alture di Shen'dar.", enHash = {"76494bd7"}}
db[92551] = db[92551] or {}
db[92551]["progress"] = db[92551]["progress"] or {it = "Qui ci sono molti Skyborne affamati e disperati che hanno bisogno di queste provviste.", enHash = {"ed968c24"}}
db[92551] = db[92551] or {}
db[92551]["reward"] = db[92551]["reward"] or {it = "Fantastico! Senza le consegne regolari riuscivamo a malapena a sopravvivere. Collaborerò con la responsabile dei guardiani per distribuire le provviste ai cittadini che ne hanno più bisogno.", enHash = {"5bd07ce7"}}
db[92579] = db[92579] or {}
db[92579]["title"] = db[92579]["title"] or {it = "Verso Valanaar", enHash = {"96e3d289"}}
db[92579] = db[92579] or {}
db[92579]["text"] = db[92579]["text"] or {it = "Per ora il pilone e il villaggio sembrano al sicuro. Vorrei che consegnassi questo rapporto a Valennia Stormfist, a Valanaar, sul margine sud-orientale dell’isola. Valennia guida i guardiani dell’isola e deve sapere cosa è successo qui.\n\nIl culto si sta espandendo rapidamente. Finora i guardiani hanno evitato lo scontro diretto, ma quei giorni sono finiti. Valanaar dovrà prepararsi a combattere.\n\nComunque, grazie. A Shen'dar avrai sempre degli amici, $N.", enHash = {"05300026","95e584aa","30451cfe"}}
db[92579] = db[92579] or {}
db[92579]["objectives"] = db[92579]["objectives"] or {it = "Consegna il Rapporto Scritto di Aonda a Valennia Stormfist a Valanaar.", enHash = {"e788bb92"}}
db[92579] = db[92579] or {}
db[92579]["progress"] = db[92579]["progress"] or {it = "Una lettera di Aonda. Che cosa ha combinato quella scaltra abitante delle alture?", enHash = {"acc2f617"}}
db[92579] = db[92579] or {}
db[92579]["reward"] = db[92579]["reward"] or {it = "<L’espressione di Valennia si incupisce mentre legge la lettera.>\n\nAonda si è fidata di te per questa consegna e parla bene di te, quindi proverò a fidarmi anch’io. Prima di continuare, devo consultare i pochi guardiani rimasti e preparare un piano nel caso il culto attacchi qui. Per ora goditi Valanaar.\n\nSe cerchi qualcosa da fare, molti cittadini avrebbero bisogno dell’aiuto di qualcuno giovane e forte come te.", enHash = {"b96672f3","aa9afdb1","23dece71"}}
db[92596] = db[92596] or {}
db[92596]["title"] = db[92596]["title"] or {it = "L’Alto Ordine", enHash = {"775bce5f"}}
db[92596] = db[92596] or {}
db[92596]["text"] = db[92596]["text"] or {it = "L’aura di energia arcana che ti avvolge è forte, anche se non hai ricevuto l’iniziazione come mago. Sono certo che saprai affrontare le tue avventure e che il legame con la nostra antica magia ti sarà sempre di aiuto, anche se non pronuncerai mai una sola parola di potere per lanciare un incantesimo.\n\nVieni, sediamoci e parliamo del mio ordine, della natura dell’arcano qui a Zephras e delle difficoltà del nostro popolo.", enHash = {"16b0ba85","3c6c999b","d3642ab1"}}
db[92596] = db[92596] or {}
db[92596]["objectives"] = db[92596]["objectives"] or {it = "Siediti e parla con Rathiril Sunlance.", enHash = {"150ae56d"}}
db[92596] = db[92596] or {}
db[92596]["progress"] = db[92596]["progress"] or {it = "La nostra terra sta cambiando, ma forse ne verrà ancora qualcosa di buono.", enHash = {"80da4d63"}}
db[92596] = db[92596] or {}
db[92596]["reward"] = db[92596]["reward"] or {it = "La missione dell’Alto Ordine è fondamentale per la sopravvivenza del nostro popolo. Rispettiamo profondamente i nostri benefattori elementali, ma dobbiamo affrontare la realtà: se ne sono andati e siamo soli.\n\nTra le minacce interne degli Al’Aketh e l’incertezza sulla sicurezza in questo piano, è nostro destino, come Alti Nobili originari di Eldre’Thalas, usare i nostri doni affinché gli shen’dorei tornino a reggersi sulle proprie forze.", enHash = {"643c004e","f26e9312","d71f533c"}}
db[92640] = db[92640] or {}
db[92640]["title"] = db[92640]["title"] or {it = "Tempi disperati", enHash = {"9bb418cd"}}
db[92640] = db[92640] or {}
db[92640]["text"] = db[92640]["text"] or {it = "Affrontare il culto in campo aperto non è possibile. La nostra occasione migliore è sfruttare questo momento per attaccare il santuario stesso. Potremmo eliminare Lorthuna prima che completi la sua parte del piano.\n\nValennia sta preparando da tempo una strategia per un possibile assalto al santuario. L’unico problema è che ci servirà aiuto.\n\nParla con Valennia per conoscere i dettagli.", enHash = {"78e02005","6e851775","8d2b6fb3","0191ea4f","9d658d73"}}
db[92640] = db[92640] or {}
db[92640]["objectives"] = db[92640]["objectives"] or {it = "Parla con Valennia Stormfist a Valanaar e segui le sue istruzioni.", enHash = {"ad8e90c4"}}
db[92640] = db[92640] or {}
db[92640]["reward"] = db[92640]["reward"] or {it = "Le tensioni tra i Plasmavento e l’Alto Ordine sono forti, ma senza il sostegno di entrambi non potremmo sperare di attuare questo piano.", enHash = {"7a867dd5"}}
db[92642] = db[92642] or {}
db[92642]["title"] = db[92642]["title"] or {it = "Interrompere i rifornimenti", enHash = {"fc8f2860"}}
db[92642] = db[92642] or {}
db[92642]["text"] = db[92642]["text"] or {it = "Valennia ha mandato una sola persona per respingere un assalto su vasta scala... per i venti.\n\nNon sembri granché, ma accetterò qualsiasi aiuto. Dobbiamo infliggere quanti più danni possibile per fermarli in fretta. I miei non resisteranno ancora a lungo.\n\nScendi dalla collina e ostacola i loro rifornimenti. I guaritori permettono agli assalitori di continuare ad attaccare: eliminandoli, forse potremo riorganizzarci e respingerli. Anche uccidere altri cultisti sarà utile.", enHash = {"0296d9d6","25916a64","ad9d0410"}}
db[92642] = db[92642] or {}
db[92642]["objectives"] = db[92642]["objectives"] or {it = "Uccidi 4 Guaritori Al'Aketh e 8 Picchiatori Al'Aketh nelle pianure di Gustberry.", enHash = {"18d2abaf"}}
db[92642] = db[92642] or {}
db[92642]["reward"] = db[92642]["reward"] or {it = "Sei ancora in vita? Ringraziamo i venti per i piccoli miracoli, suppongo.", enHash = {"64d5356f"}}
db[92643] = db[92643] or {}
db[92643]["title"] = db[92643]["title"] or {it = "Il disertore", enHash = {"eaf5b66b"}}
db[92643] = db[92643] or {}
db[92643]["text"] = db[92643]["text"] or {it = "Tra gli Al'Aketh c’è un disertore. Sostiene di conoscere le vere intenzioni del culto per l’isola e vuole consegnarsi a noi, ma solo con la garanzia di essere protetto.\n\nSi nasconde in un’abitazione isolata nelle alture, poco a nord-ovest di Valanaar. Mi serve qualcuno che possa raggiungerlo con discrezione, trovarlo e scortarlo da noi. Potrebbe essere una trappola, ma se le sue informazioni sono importanti come sostiene, vale la pena rischiare.", enHash = {"c42bc097","1bd85941","43e88eeb","5d0d9bf4","b276460a","fe13b320"}}
db[92643] = db[92643] or {}
db[92643]["objectives"] = db[92643]["objectives"] or {it = "Trova il disertore del culto nella casa appena dentro le alture a nord-ovest di Valanaar.", enHash = {"95fb8264"}}
db[92643] = db[92643] or {}
db[92643]["reward"] = db[92643]["reward"] or {it = "<L’uomo è chiaramente morto, ucciso dagli assassini affrontati fuori dalla casa. Quando ti inginocchi per esaminare il corpo, noti il riflesso di qualcosa di lucente...>", enHash = {"ee2634f3"}}
db[92644] = db[92644] or {}
db[92644]["title"] = db[92644]["title"] or {it = "Notizie sfortunate", enHash = {"5fca0b1e"}}
db[92644] = db[92644] or {}
db[92644]["text"] = db[92644]["text"] or {it = "<Infili una mano sotto il corpo ancora caldo del cultista disertore e recuperi un piccolo cristallo blu luminoso. Sembra danneggiato, ma potrebbe essere comunque importante. L’Alto Anziano Shadowsong potrebbe essere interessato.>", enHash = {"419b0339"}}
db[92644] = db[92644] or {}
db[92644]["objectives"] = db[92644]["objectives"] or {it = "Consegna il cristallo luminoso a Talanaanis Shadowsong a Valanaar.", enHash = {"f8691d4c"}}
db[92644] = db[92644] or {}
db[92644]["progress"] = db[92644]["progress"] or {it = "Sei di ritorno? E... senza nessuno?", enHash = {"1c561598"}}
db[92644] = db[92644] or {}
db[92644]["reward"] = db[92644]["reward"] or {it = "Il disertore era già morto quando sei arrivato? Una notizia davvero sfortunata.\n\n<Consegni il cristallo trovato sul corpo del cultista.>\n\nInteressante...", enHash = {"4b8a9c15","60c74705","640fccb1"}}
db[92645] = db[92645] or {}
db[92645]["title"] = db[92645]["title"] or {it = "Spezzare la Spezzatrice", enHash = {"b5f2a720"}}
db[92645] = db[92645] or {}
db[92645]["text"] = db[92645]["text"] or {it = "Sarà difficile respingere questo attacco senza eliminare il comandante del culto. La chiamano Belguilos «la Spezzatrice», ed è un vero terrore. Era una guardiana prima che il culto sfuggisse al controllo, e già allora era... strana. Posso solo immaginare quanto sia peggiorata ora che è una cultista.\n\nForse ti sto mandando a morire, ma qualcuno deve eliminare Belguilos se vogliamo sopravvivere. La troverai nella villa ai piedi della collina. Buona fortuna, $C.", enHash = {"ef84b5ff","bd61175f","3dc4f875"}}
db[92645] = db[92645] or {}
db[92645]["objectives"] = db[92645]["objectives"] or {it = "Uccidi il Comandante Belguilos nelle pianure di Gustberry.", enHash = {"f95d6630"}}
db[92645] = db[92645] or {}
db[92645]["reward"] = db[92645]["reward"] or {it = "Belguilos è morta? Che i quattro venti ti benedicano, $C.\n\nForse riusciremo davvero a uscirne vivi.", enHash = {"61fb7482","4c97babe","1a8c4954"}}
db[92646] = db[92646] or {}
db[92646]["title"] = db[92646]["title"] or {it = "Affronta Lorthuna", enHash = {"e6fe5e1e"}}
db[92646] = db[92646] or {}
db[92646]["text"] = db[92646]["text"] or {it = "Lorthuna è fuggita sulle guglie soprastanti usando una sorta di portale. Ayessa ed Elaadrin l’hanno inseguita. È successo pochi istanti fa.\n\nTemo di aver subito troppi colpi: io mi fermo qui. Attraversa il portale, trova Ayessa e aiutali a fermare Lorthuna.\n\nA meno che i rinforzi richiesti da Elaadrin e Ayessa non arrivino presto, da qui dovrai cavartela da te. Buona fortuna, $C.", enHash = {"ca213923","799b7e35","05a0d7e1"}}
db[92646] = db[92646] or {}
db[92646]["objectives"] = db[92646]["objectives"] or {it = "Attraversa il portale per le Guglie di Rohashi e raggiungi Elaadrin Evengale e Ayessa Dawnsinger nello scontro con l’Alta Sacerdotessa Lorthuna.", enHash = {"f8ef9b24"}}
db[92646] = db[92646] or {}
db[92646]["reward"] = db[92646]["reward"] or {it = "Ho mandato alcuni guaritori ad assicurarsi che Valennia e le sue forze rimaste tornassero sane e salve. Ora dovrebbe riposare nella residenza dell’Alto Anziano.\n\nMuln è già tornato ad Azeroth, ma abbiamo parlato del futuro dei Plasmavento e della nostra missione. Purtroppo l’isola è più vulnerabile che mai e ci serve un piano per proteggere Zephras da ciò che verrà.", enHash = {"0f3abdab","bdbbd6b3","9d0c07c9"}}
db[92679] = db[92679] or {}
db[92679]["title"] = db[92679]["title"] or {it = "Il tributo di sangue", enHash = {"49f51836"}}
db[92679] = db[92679] or {}
db[92679]["text"] = db[92679]["text"] or {it = "S-salve. Hai l’aria di qualcuno che sappia affrontare un’avventura. Io...\n\n<L’uomo Skyborne sussulta, chiaramente tormentato da un dolore terribile.>\n\n...mi chiedevo se cercassi lavoro. Sono venuto a Valanaar per reclutare combattenti che mi aiutino a salvare la fattoria. Se ti interessa, cerca mia moglie Aamelia Windfield nel nostro frutteto, nelle pianure a ovest di Valanaar.", enHash = {"ee7f465c","6b9dad84","676ea3c4"}}
db[92679] = db[92679] or {}
db[92679]["objectives"] = db[92679]["objectives"] or {it = "Ascolta Alvarion Windfield e trova Aamelia Windfield nel Frutteto Windfield.", enHash = {"794e17ef"}}
db[92679] = db[92679] or {}
db[92679]["progress"] = db[92679]["progress"] or {it = "Cosa? Alvarion è vivo?", enHash = {"39ef2b59"}}
db[92679] = db[92679] or {}
db[92679]["reward"] = db[92679]["reward"] or {it = "<Aamelia ascolta mentre racconti cosa è successo ad Alvarion.>\n\nAlmeno so che a Valanaar sarà al sicuro.\n\nMi spiace dirtelo, ma credo che quell’idiota di mio marito ti abbia mandato qui a morire per niente. Se hai un po’ di buon senso, vattene subito. Questa non è la tua battaglia.", enHash = {"e700c66d","8c01aa1b","97609ddb"}}
db[92685] = db[92685] or {}
db[92685]["title"] = db[92685]["title"] or {it = "Le colline hanno gli occhi", enHash = {"2980d61d"}}
db[92685] = db[92685] or {}
db[92685]["text"] = db[92685]["text"] or {it = "I banditi hanno accampamenti ovunque, e ce n’è uno piccolo sulle colline poco a nord. Vai lassù e comincia a spaccare qualche cranio. Se li cogliamo di sorpresa e li eliminiamo prima che vengano a cercarci, forse riusciremo a riequilibrare le forze e avere una possibilità.\n\nPortami le loro maschere. Più sono insanguinate, meglio è.", enHash = {"5089c301","98eeeeaf","b16e3845"}}
db[92685] = db[92685] or {}
db[92685]["objectives"] = db[92685]["objectives"] or {it = "Recupera 7 Maschere Insanguinate dei Banditi dai Banditi Predoni nelle pianure di Gustberry.", enHash = {"0cb7b1ca"}}
db[92685] = db[92685] or {}
db[92685]["progress"] = db[92685]["progress"] or {it = "Se mi porti abbastanza maschere, forse ne cucirò una coperta da regalare a Ferauu.\n\n<Aamelia ride forte.>", enHash = {"a90ae6c4","24670b00","808da916"}}
db[92685] = db[92685] or {}
db[92685]["reward"] = db[92685]["reward"] or {it = "Quando ho detto che più erano insanguinate meglio era, mi hai ascoltata davvero. Bene. Significa che li hai fatti soffrire.\n\nParlando seriamente, grazie. Da settimane vagavo per la fattoria senza scopo, come se aspettassi soltanto la fine. Credo di ricominciare a sperare.\n\nFerauu e i suoi scagnozzi arriveranno presto. Resta solo da affrontarli. Vuoi restare con me fino alla fine?", enHash = {"edb062a2","3cae743a","d492a37a"}}
db[92693] = db[92693] or {}
db[92693]["title"] = db[92693]["title"] or {it = "Mantenere la posizione", enHash = {"2622b92f"}}
db[92693] = db[92693] or {}
db[92693]["text"] = db[92693]["text"] or {it = "Hai fatto molto per darci una possibilità. Anche se morissimo oggi, sapremmo almeno di avercela messa tutta.\n\nÈ la tua ultima occasione. Se vuoi tornare a Valanaar e vivere un altro giorno, non ti biasimerò.\n\nSe invece hai un debole per le cause perse, dimmi quando vuoi cominciare. Usciremo a testa alta e accadrà quel che deve accadere.", enHash = {"f5a63235","d9e3c23b","5adcc87b"}}
db[92693] = db[92693] or {}
db[92693]["objectives"] = db[92693]["objectives"] or {it = "Parla con Aamelia Windfield quando vuoi affrontare il capo dei banditi.", enHash = {"8d5ffa2a"}}
db[92693] = db[92693] or {}
db[92693]["progress"] = db[92693]["progress"] or {it = "Non ci sono abbastanza mele della tempesta a Skywall per ripagarti.", enHash = {"b02011a7"}}
db[92693] = db[92693] or {}
db[92693]["reward"] = db[92693]["reward"] or {it = "Io... non riesco a credere che sia finita. Devo fermarmi e calmarmi prima che il cuore mi salti fuori dal petto.", enHash = {"85a45fa7"}}
db[92699] = db[92699] or {}
db[92699]["title"] = db[92699]["title"] or {it = "Il Magistro Supremo", enHash = {"e66162fa"}}
db[92699] = db[92699] or {}
db[92699]["text"] = db[92699]["text"] or {it = "Ora che sei a Valanaar, probabilmente vorrai incontrare gli altri membri dell’Alto Ordine. L’attuale Magistro Supremo, Elaadrin Evengale, e i suoi operano dalla dimora nell’estremità sud-orientale della città.\n\nDevi anche fare attenzione: qui l’Alto Ordine e i Plasmavento non vanno molto d’accordo. Sii prudente e tieniti a distanza dai Plasmavento. Abbiamo già abbastanza problemi con il culto: non tollererò scontri tra fazioni nelle strade di Valanaar.", enHash = {"9bcc07ab","6af233ab","f8208141"}}
db[92699] = db[92699] or {}
db[92699]["objectives"] = db[92699]["objectives"] or {it = "Trova Elaadrin Evengale a Valanaar.", enHash = {"b2d20fa3"}}
db[92699] = db[92699] or {}
db[92699]["reward"] = db[92699]["reward"] or {it = "Salve, e benvenuto. Rathiril mi ha inviato una missiva magica: diceva che hai del potenziale.\n\nOra capisco perché ti ha suggerito di cercarmi. Hai un’aura arcana vibrante. Ormai pochi di noi possiedono il talento, e ancor meno la volontà, di fare ciò che serve per salvare la nostra casa. Hai il coraggio e la forza per aiutare l’Alto Ordine?\n\nLo vedremo.", enHash = {"5626879d","c45d80df","b56ab28b"}}
db[92700] = db[92700] or {}
db[92700]["title"] = db[92700]["title"] or {it = "La Grande Veggente del Cielo", enHash = {"0d517e9d"}}
db[92700] = db[92700] or {}
db[92700]["text"] = db[92700]["text"] or {it = "Ora che sei a Valanaar, probabilmente vorrai incontrare gli altri Plasmavento. L’attuale Grande Veggente del Cielo e i suoi operano dalla dimora vicino al centro della città.\n\nSappi inoltre che da queste parti i Plasmavento e l’Alto Ordine non vanno molto d’accordo. Sii prudente e tieniti a distanza dall’Alto Ordine. Abbiamo già abbastanza problemi con il culto: non tollererò scontri tra fazioni nelle strade di Valanaar.", enHash = {"5d2c53e4","9be3df0c","908e36a2"}}
db[92700] = db[92700] or {}
db[92700]["objectives"] = db[92700]["objectives"] or {it = "Trova Ayessa Dawnsinger a Valanaar.", enHash = {"ddbcc95a"}}
db[92700] = db[92700] or {}
db[92700]["reward"] = db[92700]["reward"] or {it = "L’Anziano Amberwind mi ha scritto di te e delle tue imprese a Shen’dar. Qui sei il benvenuto.\n\nHai un’aura forte e una chiara affinità con gli spiriti. Sempre meno di noi possiedono la vista del cielo, e Zephras ha bisogno di chi ha questo dono per superare questi tempi difficili. Sono lieta che tu mi abbia trovata.\n\nSpero di conoscerti meglio.", enHash = {"be91123f","81c4b1cb","d73b691f"}}
db[92701] = db[92701] or {}
db[92701]["title"] = db[92701]["title"] or {it = "Verso Valanaar", enHash = {"96e3d289"}}
db[92701] = db[92701] or {}
db[92701]["text"] = db[92701]["text"] or {it = "Per ora il pilone e il villaggio sembrano al sicuro. Vorrei che consegnassi questo rapporto a Valennia Stormfist, a Valanaar, sul margine sud-orientale dell’isola. Valennia guida i guardiani dell’isola e deve sapere cosa è successo qui.\n\nIl culto si sta espandendo rapidamente. Finora i guardiani hanno evitato lo scontro diretto, ma quei giorni sono finiti. Valanaar dovrà prepararsi a combattere.\n\nComunque, grazie. A Shen'dar avrai sempre degli amici, $N.", enHash = {"05300026","95e584aa","30451cfe"}}
db[92701] = db[92701] or {}
db[92701]["objectives"] = db[92701]["objectives"] or {it = "Consegna il Rapporto Scritto di Aonda a Valennia Stormfist a Valanaar.", enHash = {"e788bb92"}}
db[92701] = db[92701] or {}
db[92701]["progress"] = db[92701]["progress"] or {it = "Una lettera di Aonda. Che cosa ha combinato quella scaltra abitante delle alture?", enHash = {"acc2f617"}}
db[92701] = db[92701] or {}
db[92701]["reward"] = db[92701]["reward"] or {it = "<L’espressione di Valennia si incupisce mentre legge la lettera.>\n\nAonda si è fidata di te per questa consegna e parla bene di te, quindi proverò a fidarmi anch’io. Prima di continuare, devo consultare i pochi guardiani che mi restano e preparare un piano nel caso il culto attacchi qui. Per ora goditi Valanaar.\n\nSe cerchi qualcosa da fare, molti cittadini avrebbero bisogno dell’aiuto di qualcuno giovane e forte come te.", enHash = {"3664b552","c0f7298e","998b83ba"}}
db[92703] = db[92703] or {}
db[92703]["title"] = db[92703]["title"] or {it = "Porta la notizia", enHash = {"8719a9bd"}}
db[92703] = db[92703] or {}
db[92703]["text"] = db[92703]["text"] or {it = "Dopo tutto questo non mi sembra giusto continuare a trattarti come qualcuno di passaggio, quindi... grazie, $N.\n\nSe torni da quelle parti e non ti dispiace, racconta ad Alvarion cosa è successo. Digli anche che, quando si sarà rimesso in piedi, dovrà portare qui un Plasmavento a esaminare quel costrutto, per assicurarci che sia sicuro averlo vicino alla nostra... alla nostra famiglia.\n\n<Aamelia si accarezza dolcemente il ventre.>\n\nQuesto ancora non lo sa. Per ora teniamolo tra noi.", enHash = {"28d0df5f","b51d35ed","87969c71","76eaa285","b3b0b487"}}
db[92703] = db[92703] or {}
db[92703]["objectives"] = db[92703]["objectives"] or {it = "Parla con Alvarion Windfield a Valanaar.", enHash = {"81afc7c5"}}
db[92708] = db[92708] or {}
db[92708]["title"] = db[92708]["title"] or {it = "Una grande avventura", enHash = {"b5c3d73d"}}
db[92708] = db[92708] or {}
db[92708]["text"] = db[92708]["text"] or {it = "I Plasmavento stanno lavorando duramente per affrontare la crisi di Zephras. Nella ricerca degli spiriti del vento scomparsi abbiamo fatto scoperte sorprendenti e stiamo elaborando un piano che potrebbe darci i mezzi per salvare l’isola.\n\nPer riuscirci ci serviranno giovani capaci come te. Se hai un momento, parliamone ancora.", enHash = {"18c5425c","fee30582","2c8d2f98"}}
db[92708] = db[92708] or {}
db[92708]["objectives"] = db[92708]["objectives"] or {it = "Ascolta ciò che Ayessa Dawnsinger ha da dirti.", enHash = {"9cd3fece"}}
db[92708] = db[92708] or {}
db[92708]["reward"] = db[92708]["reward"] or {it = "Ora capisci? Fuori da Skywall ci sono conoscenze e possibilità inesplorate. Questa resterà sempre la nostra casa, ma credo che la via della salvezza sia laggiù. Dobbiamo raggiungere Azeroth e ottenere il potere e i mezzi per salvare Zephras. Questa è la strada.\n\nAvrai il coraggio di unirti a noi quando sarà il momento?", enHash = {"c46a60ad","a2b9fb03","bf19f7ad"}}
db[92709] = db[92709] or {}
db[92709]["title"] = db[92709]["title"] or {it = "Una grande avventura", enHash = {"b5c3d73d"}}
db[92709] = db[92709] or {}
db[92709]["text"] = db[92709]["text"] or {it = "La tua discendenza dagli Alti Nobili risplende nei tuoi occhi, limpida come il cielo sopra di noi. Sei dei nostri, e saranno giovani come te ad aiutarci a salvare la nostra casa. Ma prima lascia che ti racconti la nostra missione e i nostri progetti qui a Zephras... e oltre.", enHash = {"6104f0ba"}}
db[92709] = db[92709] or {}
db[92709]["objectives"] = db[92709]["objectives"] or {it = "Ascolta ciò che Elaadrin Evengale a Valanaar ha da dirti.", enHash = {"221de764"}}
db[92709] = db[92709] or {}
db[92709]["reward"] = db[92709]["reward"] or {it = "Ora capisci? Riscoprire la magia antica dei nostri antenati è la chiave dei segreti di Zephras e del nostro futuro. Per salvare la nostra casa dobbiamo recuperare ciò che abbiamo perduto nei millenni.\n\nAzeroth è la chiave. Il Kirin Tor ci mostrerà la strada.\n\nMentre ci prepariamo a partire, incontra gli altri membri dell’Alto Ordine a Valanaar. Molti hanno incarichi per cui servirebbe il tuo aiuto.", enHash = {"1a4860a2","3eab7448","6202ff9c"}}
db[92727] = db[92727] or {}
db[92727]["title"] = db[92727]["title"] or {it = "Lo studioso scomparso", enHash = {"b119d87d"}}
db[92727] = db[92727] or {}
db[92727]["text"] = db[92727]["text"] or {it = "La ricerca della conoscenza è il compito principale dell’Alto Ordine, ma a Zephras non è mai stata tanto pericolosa.\n\nUno dei nostri studiosi, Fillion Flamebreeze, era diretto alle alture di Shen’dar per esaminare la magia del vento che si concentra in alcune zone. Purtroppo non è tornato e temiamo che gli sia successo qualcosa lungo la strada.\n\nSe puoi, trovalo per noi. È stato visto l’ultima volta sulla strada che da Valanaar conduce a ovest, verso le alture di Shen’dar.", enHash = {"6c2f2b3d","08501fbd","eaf4137d"}}
db[92727] = db[92727] or {}
db[92727]["objectives"] = db[92727]["objectives"] or {it = "Scopri cosa è accaduto a Fillion Flamebreeze.", enHash = {"5a2c1662"}}
db[92727] = db[92727] or {}
db[92727]["reward"] = db[92727]["reward"] or {it = "<La borsa davanti a te ha sul risvolto alcune macchie che sembrano sangue secco. Esaminandole, noti anche un nome ricamato: «Fillion Flamebreeze».>", enHash = {"6a1b473b"}}
db[92741] = db[92741] or {}
db[92741]["title"] = db[92741]["title"] or {it = "Visitatori indesiderati", enHash = {"57a8095c"}}
db[92741] = db[92741] or {}
db[92741]["text"] = db[92741]["text"] or {it = "La Foresta di Shadowgale è estremamente pericolosa e di solito è vietata ai normali avventurieri. Negli ultimi mesi la popolazione degli strillatori è cresciuta enormemente e ha iniziato a espandersi oltre il bosco: potrebbe diventare un problema. Mi interessano le proprietà alchemiche dei loro artigli, quindi ridurne il numero sarebbe anche un’occasione per i nostri studi.\n\nRaggiungi la foresta e caccia quelle bestie. Portami quanti più artigli puoi.", enHash = {"1f0680cc","535b4c7a","2ddfbc24"}}
db[92741] = db[92741] or {}
db[92741]["objectives"] = db[92741]["objectives"] or {it = "Raggiungi la Foresta di Shadowgale e raccogli 8 Artigli di Strillatore per Iaadaria Bitterwind a Valanaar.", enHash = {"1d4176bd"}}
db[92741] = db[92741] or {}
db[92741]["progress"] = db[92741]["progress"] or {it = "L’Alto Ordine non è solito dedicarsi al lavoro di cacciatori e guardiacaccia, ma se un servizio alla comunità può favorire gli studi, siamo lieti di prestarlo.", enHash = {"1a9981cb"}}
db[92741] = db[92741] or {}
db[92741]["reward"] = db[92741]["reward"] or {it = "Hai portato una bella quantità di artigli. Non vedo l’ora di studiarli!\n\nGrazie per il tuo servizio all’Alto Ordine, $C.", enHash = {"3d09977a","ad911c5e","72256308"}}
db[92849] = db[92849] or {}
db[92849]["title"] = db[92849]["title"] or {it = "Lo studioso scomparso", enHash = {"b119d87d"}}
db[92849] = db[92849] or {}
db[92849]["text"] = db[92849]["text"] or {it = "<Da ciò che hai trovato, è molto probabile che a Fillion sia accaduta una disgrazia. Potrebbe essere ancora nelle vicinanze e avere bisogno di aiuto. Noti una grotta poco più a nord: dovresti continuare a cercarlo lì.>", enHash = {"49aa1624"}}
db[92849] = db[92849] or {}
db[92849]["objectives"] = db[92849]["objectives"] or {it = "Continua a cercare Fillion Flamebreeze.", enHash = {"350ee713"}}
db[92849] = db[92849] or {}
db[92849]["reward"] = db[92849]["reward"] or {it = "G-grazie. Tornavo a Valanaar quando un’ombra enorme è comparsa sopra di me. Ho alzato lo sguardo e ho visto una bestia gigantesca e terribile piombarmi addosso dal cielo. Ho tentato di fuggire, ma sono stato colpito e tutto è diventato buio.\n\nCredo proprio che senza di te sarei diventato la cena di quella bestia e dei suoi piccoli.", enHash = {"075d4f28","597a9bf0","c0d2dc9a"}}
db[92850] = db[92850] or {}
db[92850]["title"] = db[92850]["title"] or {it = "Lo studioso scomparso", enHash = {"b119d87d"}}
db[92850] = db[92850] or {}
db[92850]["text"] = db[92850]["text"] or {it = "Mi sento già molto meglio. Conosco un po’ le arti arcane e Valanaar è vicina: posso farcela da solo. Più importante della mia sicurezza, però, è il pericolo di questi strillatori, che hanno nidificato così vicino alla città. Se vuoi farmi un favore, torna dentro e prendi la testa di quella bestia!\n\nQuando avrai finito, mi troverai con Dondallion a Valanaar. Devo tornare da lui al più presto. Probabilmente è fuori di sé dalla preoccupazione.", enHash = {"974ce6c0","f010dbfe","56c01a14"}}
db[92850] = db[92850] or {}
db[92850]["objectives"] = db[92850]["objectives"] or {it = "Uccidi la Matriarca degli Strillatori nella loro tana e porta la sua testa a Dondallion Whisperwind a Valanaar.", enHash = {"795a0ea5"}}
db[92850] = db[92850] or {}
db[92850]["progress"] = db[92850]["progress"] or {it = "Quello sciocco di Fillion...", enHash = {"c2e6d02a"}}
db[92850] = db[92850] or {}
db[92850]["reward"] = db[92850]["reward"] or {it = "Devo ammettere che sono immensamente sollevato dal ritorno di Fillion. Non è mai stato bravo a prestare attenzione a ciò che lo circonda: è sempre perso nei pensieri o con il naso in un libro.\n\nGrazie, $C.", enHash = {"b0a7deaf","f898fb9f","b1741d35"}}
db[92880] = db[92880] or {}
db[92880]["title"] = db[92880]["title"] or {it = "Ritorno a Valanaar", enHash = {"41847399"}}
db[92880] = db[92880] or {}
db[92880]["text"] = db[92880]["text"] or {it = "Ci vorrà un po’ per eliminare gli ultimi assalitori, ma ora le nostre possibilità sono molto migliori. Torna a Valanaar e riferisci che qui la situazione è stabile.\n\nNon potrò mai ringraziarti abbastanza. Senza di te saremmo messi molto peggio. Avevo chiesto rinforzi e ho ricevuto invece una promessa di eroismo. Mi va bene così.\n\nChe i quattro venti ti benedicano, $C.", enHash = {"36f120aa","ab486672","8e994532"}}
db[92880] = db[92880] or {}
db[92880]["objectives"] = db[92880]["objectives"] or {it = "Porta il Rapporto di Yorna a Valennia Stormfist a Valanaar.", enHash = {"53938dda"}}
db[92880] = db[92880] or {}
db[92880]["reward"] = db[92880]["reward"] or {it = "<Valennia appare visibilmente sollevata mentre le racconti la situazione della torre orientale.>\n\nGrazie ai venti.", enHash = {"ab290cb7","63320603","51cb1a19"}}
db[92881] = db[92881] or {}
db[92881]["title"] = db[92881]["title"] or {it = "La richiesta dell’Alto Anziano", enHash = {"cbee6af6"}}
db[92881] = db[92881] or {}
db[92881]["text"] = db[92881]["text"] or {it = "Gli attacchi alle torri di guardia orientale e occidentale non sono una coincidenza. Da quello che ci hai raccontato sul sacerdote del cielo alla torre occidentale, sospettiamo che il culto voglia fare qualcosa ai piloni di ancoraggio.\n\nParla con l’Alto Anziano Shadowsong. Ti illustrerà una pista che potrebbe essere promettente.", enHash = {"f05acb60","19d4945a","677c9670","3ef8b5fb","ead16a5f","38796c75"}}
db[92881] = db[92881] or {}
db[92881]["objectives"] = db[92881]["objectives"] or {it = "Parla con Talaanis Shadowsong a Valanaar.", enHash = {"71321ddf"}}
db[92881] = db[92881] or {}
db[92881]["reward"] = db[92881]["reward"] or {it = "Ho una piccola faccenda che richiede proprio l’aiuto di qualcuno capace di affrontare avventure come te.", enHash = {"eb010df2"}}
db[92947] = db[92947] or {}
db[92947]["title"] = db[92947]["title"] or {it = "La nostra mossa", enHash = {"78cf8d7a"}}
db[92947] = db[92947] or {}
db[92947]["text"] = db[92947]["text"] or {it = "Ci siamo tutti, bene. Ho appena mandato alcuni dei miei migliori combattenti dall’ingresso principale del santuario per creare scompiglio e distrarre il nemico, mentre io guiderò i Plasmavento e l’Alto Ordine sul fianco.\n\nSe tutto va bene, sfonderemo in fretta ed elimineremo l’Alta Sacerdotessa. Tu entra e comincia a spaccare qualche cranio. Dopo aver seminato un po’ di caos, raggiungi la mia vice, Hyusaa Quickbreeze, presso i gradini del santuario.\n\nChe i venti ti guidino, $C.", enHash = {"cb4d21c1","6fcbe29b","7fd7745b"}}
db[92947] = db[92947] or {}
db[92947]["objectives"] = db[92947]["objectives"] or {it = "Uccidi 7 Guardiani Al'Aketh, 7 Evocatori degli Spiriti Al'Aketh e 7 Maestri di Spada Al'Aketh, poi presentati a Hyusaa Quickbreeze al Santuario di Akir.", enHash = {"9d211280"}}
db[92947] = db[92947] or {}
db[92947]["reward"] = db[92947]["reward"] or {it = "Abbiamo combattuto duramente per arrivare fin qui, ma non è ancora finita.", enHash = {"91672697"}}
db[93036] = db[93036] or {}
db[93036]["title"] = db[93036]["title"] or {it = "Infiltrarsi nel culto", enHash = {"5ff6f4bc"}}
db[93036] = db[93036] or {}
db[93036]["text"] = db[93036]["text"] or {it = "Forse non lo sai, ma Sania Silverstream è una «missionaria» degli Al'Aketh. Amano fingere di essere un normale ordine religioso e mandano emissari dall’aria innocua a reclutare. Finora abbiamo tollerato Sania per evitare uno scontro diretto con il culto, ma è chiaro che questa illusione di pace non durerà ancora a lungo.\n\nQui sei appena arrivato e quasi nessuno ti conosce. Vorrei vedere se puoi sfruttare Sania per avvicinarti al culto e scoprire quali siano i loro piani per il villaggio.", enHash = {"c31891e1","72fa540f","e232d8b9"}}
db[93036] = db[93036] or {}
db[93036]["objectives"] = db[93036]["objectives"] or {it = "Parla con Sania Silverstream nel villaggio di Shen'dar.", enHash = {"0e1d601a"}}
db[93036] = db[93036] or {}
db[93036]["reward"] = db[93036]["reward"] or {it = "Salve, giovane. Sono Sania Silverstream, una sacerdotessa novizia dell’Ordine degli Al’Aketh. Vuoi conoscere meglio il nostro sovrano, il Signore del Vento Al’Akir?\n\nAlla sua tavola c’è sempre posto per i giusti e per chi si pente.", enHash = {"570ca97b","bbb7e5af","bef70459"}}
db[93065] = db[93065] or {}
db[93065]["title"] = db[93065]["title"] or {it = "Prepararsi alla battaglia", enHash = {"d5d698a8"}}
db[93065] = db[93065] or {}
db[93065]["text"] = db[93065]["text"] or {it = "I guardiani si stanno mobilitando e ci prepariamo tutti a partire. Fai ciò che ti serve e raggiungici sulla strada orientale che esce dalla città verso nord. Faremo un ultimo controllo con tutti prima di muoverci.", enHash = {"c52fb54d"}}
db[93065] = db[93065] or {}
db[93065]["objectives"] = db[93065]["objectives"] or {it = "Parla con Valennia Stormfist nelle pianure di Gustberry.", enHash = {"c18fbf02"}}
db[93065] = db[93065] or {}
db[93065]["reward"] = db[93065]["reward"] or {it = "Non saremo mai più pronti di così.", enHash = {"42e2ff91"}}
db[93089] = db[93089] or {}
db[93089]["title"] = db[93089]["title"] or {it = "Il prossimo passo", enHash = {"a1cf3160"}}
db[93089] = db[93089] or {}
db[93089]["text"] = db[93089]["text"] or {it = "Ringrazia Elaadrin da parte mia per tutto ciò che l’Alto Ordine e i vostri nuovi amici del «Kirin Tor» hanno fatto per Zephras. So che l’Alto Ordine intende lasciare l’isola: questa spedizione ha la mia benedizione e i miei migliori auguri.\n\nSpero soltanto che la soluzione arcana che troverete possa davvero darci la stabilità che ci manca da anni. Se intendi partire con loro... beh, la sua missione ne uscirà rafforzata.\n\nChe i venti siano con te, $N.", enHash = {"8bc2251f","6053fb65","774ca591"}}
db[93089] = db[93089] or {}
db[93089]["objectives"] = db[93089]["objectives"] or {it = "Parla con Elaadrin Evengale quando vuoi lasciare Zephras.", enHash = {"5b7fa367"}}
db[93089] = db[93089] or {}
db[93089]["reward"] = db[93089]["reward"] or {it = "Mi rallegra sapere che l’Alto Anziano Shadowsong benedice la spedizione. Ora che il culto è sconfitto e i preparativi sono conclusi, credo sia finalmente il momento.\n\nAnsirem ha lavorato molto per rendere stabile il trasporto sulle navi volanti tra Dalaran e Zephras. Abbiamo fatto tutte le prove possibili: è ora che l’avanguardia parta.", enHash = {"0b2de642","a8d2913e","6c00b268"}}
db[93090] = db[93090] or {}
db[93090]["title"] = db[93090]["title"] or {it = "Il prossimo passo", enHash = {"a1cf3160"}}
db[93090] = db[93090] or {}
db[93090]["text"] = db[93090]["text"] or {it = "Ringrazia Ayessa da parte mia per tutto ciò che i Plasmavento e i vostri nuovi amici del «Circolo della Terra» hanno fatto per Zephras. So del progetto di portare gli sciamani dei Plasmavento fuori dall’isola: questa spedizione ha la mia benedizione e i miei migliori auguri.\n\nSpero soltanto che la soluzione che troverete possa davvero darci la stabilità che ci manca da anni.\n\nChe i venti siano con te, $N.", enHash = {"2f04ccb2","1090a538","e00c5578","17907a51","f9192e97","c894ded7"}}
db[93090] = db[93090] or {}
db[93090]["objectives"] = db[93090]["objectives"] or {it = "Parla con Ayessa Dawnsinger quando vuoi lasciare Zephras.", enHash = {"3a7dc11e"}}
db[93090] = db[93090] or {}
db[93090]["reward"] = db[93090]["reward"] or {it = "Sono lieta che l’Alto Anziano Shadowsong benedica la spedizione. Ora che il culto è sconfitto e i preparativi sono conclusi, credo sia finalmente il momento.\n\nMuln ha lavorato molto per rendere stabile il trasporto sulle navi volanti tra Zephras e Mulgore, dove vive il Circolo della Terra. Abbiamo effettuato viaggi di prova e alcuni dei nostri ci aspettano già dall’altra parte.", enHash = {"6f358cfd","4033f7e1","58cf5d0b"}}
db[93159] = db[93159] or {}
db[93159]["title"] = db[93159]["title"] or {it = "Lo strano eremita", enHash = {"61cc7bd6"}}
db[93159] = db[93159] or {}
db[93159]["text"] = db[93159]["text"] or {it = "Ehm, uhm... s-salve, volevo dire, ciao! Anzi, saluti! Scusa... è passato tanto tempo da quando ho parlato con un’altra persona. Temo di essere un po’ arrugginito.\n\n<La strana figura incappucciata si muove a disagio davanti a te.>\n\nAllora, ehm... come va la giornata?", enHash = {"b56dd006","99280272","b05552b2"}}
db[93159] = db[93159] or {}
db[93159]["objectives"] = db[93159]["objectives"] or {it = "Parla con lo Strano Eremita nella Foresta di Shadowgale per conoscerlo meglio.", enHash = {"28d533f9"}}
db[93159] = db[93159] or {}
db[93159]["progress"] = db[93159]["progress"] or {it = "E questa è la storia...", enHash = {"ec4e9e51"}}
db[93159] = db[93159] or {}
db[93159]["reward"] = db[93159]["reward"] or {it = "...questo è più o meno tutto. Prima ero... uhm... da un’altra parte. Ora sono qui, con i miei amici e le mie cose. C-cose che ho costruito, intendo. Non mi serve altro. Credo.\n\nPerò è bello parlare con qualcuno che risponde. Gli spiriti della foresta ci provano, ma finiscono per cantarmi. È piacevole a modo suo, ma non è proprio una conversazione s-stimolante.", enHash = {"62bbe614","5581ca98","1c7310c2"}}
db[93160] = db[93160] or {}
db[93160]["title"] = db[93160]["title"] or {it = "I doni della foresta", enHash = {"2cab60f3"}}
db[93160] = db[93160] or {}
db[93160]["text"] = db[93160]["text"] or {it = "Grazie davvero per esserti fermato a parlare con me! S-se vuoi aiutarmi, mi farebbe comodo una mano a raccogliere le ghiande dal terreno. Ho già preso quasi tutte quelle qui vicino, ma nella foresta ci sono tantissime di quelle specie di uccelli rapaci. È pericoloso là fuori e preferirei non diventare il pranzo di un uccello gigante!\n\nQuindi, se vuoi, potresti raccoglierle per me? Ci preparerò qualcosa di buono!", enHash = {"d7a91787","0b9027b7","f8e079e1"}}
db[93160] = db[93160] or {}
db[93160]["objectives"] = db[93160]["objectives"] or {it = "Raccogli 8 Ghiande di Shadowgale nella Foresta di Shadowgale.", enHash = {"a08ca709"}}
db[93160] = db[93160] or {}
db[93160]["progress"] = db[93160]["progress"] or {it = "Mmm, credo che ti piacerà quello che preparerò con queste ghiande!", enHash = {"c26c5a33"}}
db[93160] = db[93160] or {}
db[93160]["reward"] = db[93160]["reward"] or {it = "Grazie! Vedrai che arrostite sono deliziose.\n\nScusami un momento, non ci metterò molto a prepararle.", enHash = {"131ec95a","5b7f8b9c","963851b2"}}
db[93165] = db[93165] or {}
db[93165]["title"] = db[93165]["title"] or {it = "Pietà per orecchie sorde", enHash = {"409cb76e"}}
db[93165] = db[93165] or {}
db[93165]["text"] = db[93165]["text"] or {it = "Gli Al'Aketh hanno inflitto una terribile tragedia alla nostra comunità, e il sangue va ripagato con il sangue.\n\nHo un’offerta per te. Se affronti quei maledetti cultisti, portami le orecchie di quelli che uccidi. Ti ricompenserò con denaro per ogni orecchio e, col tempo, anche con l’accesso ai segreti degli Artigli della Notte, se dimostrerai di essere davvero dei nostri.", enHash = {"a38765c2","87559a9e","e00e4b34"}}
db[93165] = db[93165] or {}
db[93165]["objectives"] = db[93165]["objectives"] or {it = "Raccogli 10 Orecchie di Cultista Al'Aketh dai cultisti nella Foresta di Shadowgale, al Santuario di Akir o nelle pianure di Gustberry.", enHash = {"39162cd5"}}
db[93165] = db[93165] or {}
db[93165]["progress"] = db[93165]["progress"] or {it = "Non riposerò finché le mie zanne non avranno trapassato la gola di ogni cultista dell’isola.", enHash = {"50d7d412"}}
db[93165] = db[93165] or {}
db[93165]["reward"] = db[93165]["reward"] or {it = "Ottimo lavoro. Eliminare il culto può portare solo benefici. Spero capiscano che gli Artigli della Notte non vanno provocati e che il nostro rancore è profondo.\n\nAffrontare il culto ti darà parecchio da fare. Se raccogli altre orecchie, portale qui.", enHash = {"1f135df2","118c676c","46980096"}}
db[93172] = db[93172] or {}
db[93172]["title"] = db[93172]["title"] or {it = "Libera gli spiriti vuoti", enHash = {"81ed8d01"}}
db[93172] = db[93172] or {}
db[93172]["text"] = db[93172]["text"] or {it = "Quasi tutti gli elfi dell’isola pensano che questi boschi siano infestati, e non hanno torto.\n\nNelle vecchie rovine a nord-est si radunano strani spiriti simili a fantasmi. Alcune notti puoi quasi sentirli «cantare». Non assomiglia a nessuna canzone che conosca, ma è sicuramente un canto, ed è... così triste.\n\nNon so perché, ma credo che lì sia successo qualcosa di terribile e che gli spiriti siano rimasti intrappolati. Se hai coraggio, forse puoi aiutarli a liberarsi.", enHash = {"753e849c","ebe61768","f7249fa8"}}
db[93172] = db[93172] or {}
db[93172]["objectives"] = db[93172]["objectives"] or {it = "Distruggi 10 Spiriti Vuoti del Vento nella Foresta di Shadowgale.", enHash = {"eea6d286"}}
db[93172] = db[93172] or {}
db[93172]["progress"] = db[93172]["progress"] or {it = "Speriamo che quei poveri spiriti trovino pace una volta liberati da questo luogo.", enHash = {"dda75a4c"}}
db[93172] = db[93172] or {}
db[93172]["reward"] = db[93172]["reward"] or {it = "Grazie.", enHash = {"e2989dfb"}}
db[93320] = db[93320] or {}
db[93320]["title"] = db[93320]["title"] or {it = "Difesa della torre", enHash = {"5f62f829"}}
db[93320] = db[93320] or {}
db[93320]["text"] = db[93320]["text"] or {it = "Ho appena saputo che il culto sta attaccando la torre di guardia del pilone appena fuori città! Ho mandato i pochi guardiani disponibili a sfondare le retrovie nemiche e soccorrere i difensori, ma qualsiasi altro aiuto potrebbe fare la differenza tra la vita e la morte dei nostri.\n\nParti subito per la torre orientale e fai tutto ciò che puoi.\n\nLa mia luogotenente Yorana Windyreed guida i rinforzi. Se è ancora viva, ti dirà come aiutarli al meglio.", enHash = {"fa783e66","13ca51e8","61331e28"}}
db[93320] = db[93320] or {}
db[93320]["objectives"] = db[93320]["objectives"] or {it = "Presentati a Yorana Windyreed alla torre di guardia orientale nelle pianure di Gustberry.", enHash = {"637e6ff1"}}
db[93320] = db[93320] or {}
db[93320]["reward"] = db[93320]["reward"] or {it = "Per ora li tratteniamo, ma sono più numerosi e i nostri combattenti iniziano a stancarsi. Dobbiamo spezzare lo stallo, e in fretta.", enHash = {"466b6204"}}
db[93459] = db[93459] or {}
db[93459]["title"] = db[93459]["title"] or {it = "Altre orecchie Al’Aketh", enHash = {"4b7410ff"}}
db[93459] = db[93459] or {}
db[93459]["text"] = db[93459]["text"] or {it = "Di solito il culto Al'Aketh evita questa foresta, temendo le voci che la vogliono infestata... voci che siamo felici di alimentare. I druidi del mio ordine desiderano soltanto vivere in pace qui a Shadowgale, e loro minacciano quella pace.\n\nMolti di noi hanno paura.\n\nTi propongo un accordo: combatti i cultisti e portaci le orecchie di quelli che uccidi. Ti ricompenseremo con denaro e, col tempo, con l’accesso ai nostri segreti, se dimostrerai di essere davvero dei nostri.", enHash = {"b078e497","b7b8b23f","e80a44b3","cbffab5f","12528b07"}}
db[93459] = db[93459] or {}
db[93459]["objectives"] = db[93459]["objectives"] or {it = "Raccogli 10 Orecchie di Cultista Al'Aketh dagli Al'Aketh nella Foresta di Shadowgale, al Santuario di Akir o nelle pianure di Gustberry, poi portale a Vayn Moonclaw nella Foresta di Shadowgale.", enHash = {"927f8ff1"}}
db[93459] = db[93459] or {}
db[93459]["progress"] = db[93459]["progress"] or {it = "<Vayn ti rivolge un cenno.>", enHash = {"a8cf3c2e"}}
db[93459] = db[93459] or {}
db[93459]["reward"] = db[93459]["reward"] or {it = "Come promesso, ecco la tua ricompensa.", enHash = {"44d17203"}}
db[93740] = db[93740] or {}
db[93740]["title"] = db[93740]["title"] or {it = "Sangue per sangue", enHash = {"0b8a253d"}}
db[93740] = db[93740] or {}
db[93740]["text"] = db[93740]["text"] or {it = "Questa mattina alcuni novizi dei Plasmavento sono stati trovati morti nelle alture. Non ne siamo certi, ma è molto probabile che i responsabili siano gli Al'Aketh. I Plasmavento ripagano sempre il sangue con il sangue.\n\nVai a nord e uccidi ogni Al'Aketh che incontri. Portami i loro amuleti di preghiera in pietra del vento come prova. Non perdoniamo e non dimentichiamo.", enHash = {"7c3b21ee","6b9f3ad6","689cf3ec"}}
db[93740] = db[93740] or {}
db[93740]["objectives"] = db[93740]["objectives"] or {it = "Raccogli 10 Amuleti di Pietra del Vento degli Al'Aketh dai cadaveri dei cultisti nelle pianure di Gustberry.", enHash = {"c4fee261"}}
db[93740] = db[93740] or {}
db[93740]["progress"] = db[93740]["progress"] or {it = "La sanguinaria follia degli Al’Aketh dura da troppo tempo. Questo è soltanto l’inizio della resa dei conti.", enHash = {"1f77f3bd"}}
db[93835] = db[93835] or {}
db[93835]["title"] = db[93835]["title"] or {it = "Affronta Lorthuna", enHash = {"e6fe5e1e"}}
db[93835] = db[93835] or {}
db[93835]["text"] = db[93835]["text"] or {it = "Lorthuna è fuggita sulle guglie soprastanti usando una sorta di portale. Ayessa ed Elaadrin l’hanno inseguita. È successo pochi istanti fa.\n\nTemo di aver subito troppi colpi: io mi fermo qui. Attraversa il portale, trova Elaadrin e aiutali a fermare Lorthuna.\n\nA meno che i rinforzi richiesti da Elaadrin e Ayessa non arrivino presto, da qui dovrai cavartela da te. Buona fortuna, $C.", enHash = {"c1d6081d","da7d92fb","85805f27"}}
db[93835] = db[93835] or {}
db[93835]["objectives"] = db[93835]["objectives"] or {it = "Attraversa il portale per le Guglie di Rohashi e raggiungi Elaadrin Evengale e Ayessa Dawnsinger nello scontro con l’Alta Sacerdotessa Lorthuna.", enHash = {"74e12c55"}}
db[93835] = db[93835] or {}
db[93835]["reward"] = db[93835]["reward"] or {it = "Ho mandato alcuni dei maghi rimasti per assicurarmi che anche Valennia e i suoi potessero fuggire. Ora dovrebbe riposare nella residenza dell’Alto Anziano Shadowsong.\n\nAnsirem è dovuto tornare ad Azeroth, ma prima di partire abbiamo discusso i prossimi passi dell’Alto Ordine. Siamo sopravvissuti, ma Zephras è pericolosamente vulnerabile: dobbiamo prepararci a ciò che verrà.", enHash = {"b7933c3b","26505b43","308e8fed"}}
db[93836] = db[93836] or {}
db[93836]["title"] = db[93836]["title"] or {it = "Il destino di Zephras", enHash = {"10e89c1d"}}
db[93836] = db[93836] or {}
db[93836]["text"] = db[93836]["text"] or {it = "Muln mi ha parlato molto dei signori elementali e temo che abbiamo buone ragioni per avere paura di Al'Akir. Ora che le protezioni che nascondevano Zephras al suo sguardo sono cadute, siamo completamente indifesi. Se decidesse di attaccarci, qui nel suo dominio non avremmo alcuna possibilità.\n\nL’Alto Anziano Shadowsong deve conoscere il pericolo e, soprattutto, le nostre intenzioni per la missione ad Azeroth. Troveremo il modo di salvare la nostra casa. Lo giuro.", enHash = {"5d5ee83c","019a6de6","b1a14810","2e17f716","8c771bcc","3c7df5f6"}}
db[93836] = db[93836] or {}
db[93836]["objectives"] = db[93836]["objectives"] or {it = "Parla con Talaanis Shadowsong a Valanaar.", enHash = {"71321ddf"}}
db[93836] = db[93836] or {}
db[93836]["reward"] = db[93836]["reward"] or {it = "<Talaanis Shadowsong ascolta attentamente il racconto di ciò che è successo sopra il Santuario di Akir e del piano di Ayessa di lasciare Zephras.>\n\nDevo rifletterci ancora. Il lato positivo è che ci siamo liberati di Lorthuna e abbiamo privato il culto della sua guida. La nostra casa non è stata invasa e, per degli dei elementali, potrebbero passare anni, persino decenni, prima che Al’Akir ci degni della sua attenzione.\n\nAbbiamo molto da temere, ma anche molto da festeggiare.", enHash = {"d8146ab3","f45c85c5","c0ea6f99"}}
db[93926] = db[93926] or {}
db[93926]["title"] = db[93926]["title"] or {it = "La torre occidentale", enHash = {"150fc312"}}
db[93926] = db[93926] or {}
db[93926]["text"] = db[93926]["text"] or {it = "Qualunque sia il motivo per cui il culto attacca la torre, non vale la vita dei nostri.\n\nVai a sud-ovest e controlla la torre di guardia. Trova i guardiani e di’ loro di tornare al villaggio. Difendere quella torre non vale le vite che costerebbe: preferisco concentrare qui le forze rimaste per proteggere i cittadini.\n\nIl responsabile è il Guardiano Vaaniel. Digli di tornare qui il prima possibile. Presto!", enHash = {"6df08343","78ec6bc9","9655cb89"}}
db[93926] = db[93926] or {}
db[93926]["objectives"] = db[93926]["objectives"] or {it = "Trova il Guardiano Vaaniel alla torre di guardia occidentale.", enHash = {"a605b6d9"}}
db[93926] = db[93926] or {}
db[93926]["reward"] = db[93926]["reward"] or {it = "<Il corpo è ancora relativamente fresco: la morte deve essere recente. Le bruciature sulla pelle del guardiano mostrano chiaramente che è stato ucciso dagli incantatori del culto che dominano le tempeste.>", enHash = {"8d8bb3a8"}}
db[93927] = db[93927] or {}
db[93927]["title"] = db[93927]["title"] or {it = "Un’ultima richiesta", enHash = {"38786064"}}
db[93927] = db[93927] or {}
db[93927]["text"] = db[93927]["text"] or {it = "<Mentre esamini il corpo del guardiano morto, dalle sue mani cade un biglietto insanguinato. Raccoglierlo e leggerlo potrebbe aiutarti a capire come procedere.>", enHash = {"7e899d43"}}
db[93927] = db[93927] or {}
db[93927]["objectives"] = db[93927]["objectives"] or {it = "Raccogli il biglietto vicino al guardiano morto e leggilo per capire come proseguire.", enHash = {"f6d68188"}}
db[93927] = db[93927] or {}
db[93927]["progress"] = db[93927]["progress"] or {it = "Quali notizie dalla torre occidentale?", enHash = {"dbc72532"}}
db[93927] = db[93927] or {}
db[93927]["reward"] = db[93927]["reward"] or {it = "Quindi sono tutti morti. Che la tempesta maledica quei bastardi del culto!\n\nHai eliminato il sacerdote e fermato i cultisti alla torre, ma ciò che stavano facendo al pilone mi preoccupa ancora di più. L’enorme scorta di pietre del vento indica che avevano bisogno di moltissima energia.\n\nQual è il loro obiettivo? Profanare il pilone, attaccare il villaggio... a quale scopo?", enHash = {"eca4c03a","8c23c578","81cb3ba4"}}
db[93948] = db[93948] or {}
db[93948]["title"] = db[93948]["title"] or {it = "Consegna il sigillo", enHash = {"300f7b96"}}
db[93948] = db[93948] or {}
db[93948]["text"] = db[93948]["text"] or {it = "Visto che vai comunque a Valanaar, consegna l’anello con sigillo recuperato alla torre a Talaanis Shadowsong.\n\nVorrà riaverlo e, soprattutto, conoscere il destino del nipote. Talaanis è l’Alto Anziano di Zephras e, cosa ancora più importante, è un brav’uomo molto amato dal popolo, nonostante le difficoltà attuali. Mi addolora pensare a come reagirà alla notizia. Esprimigli le mie condoglianze.", enHash = {"6a9bb157","90b6d18f","371aca57","f510daf9","f004ebad"}}
db[93948] = db[93948] or {}
db[93948]["objectives"] = db[93948]["objectives"] or {it = "Consegna il Sigillo della Famiglia Shadowsong a Talaanis Shadowsong a Valanaar.", enHash = {"2607a39f"}}
db[93948] = db[93948] or {}
db[93948]["progress"] = db[93948]["progress"] or {it = "Che cosa mi porti? Oh... oh no.", enHash = {"b98e2939"}}
db[93948] = db[93948] or {}
db[93948]["reward"] = db[93948]["reward"] or {it = "Mi... addolora molto sapere che mio nipote è morto. Ti ringrazio per aver recuperato questo oggetto e avermelo riportato.\n\nNon capita spesso che dalle alture scendano giovani shen’dorei così capaci. Se cerchi lavoro, parla con Valennia Stormfist, capitano dei guardiani di Valanaar. Di questi tempi ci serve tutto l’aiuto possibile.", enHash = {"324c582a","8dc9108c","a2874022"}}
db[93949] = db[93949] or {}
db[93949]["title"] = db[93949]["title"] or {it = "Insetti in ascolto", enHash = {"addc0c52"}}
db[93949] = db[93949] or {}
db[93949]["text"] = db[93949]["text"] or {it = "Ci hanno messo sotto ascolto.\n\nÈ la stagione dei saltacieli nelle pianure, e quegli insetti sono ovunque. Un mago dell’Alto Ordine ha riferito che uno degli esemplari uccisi aveva addosso un incantamento. Esaminandolo, sembra trattarsi di una magia per ascoltare.\n\nSospettiamo che il culto li usi come spie. Vai a sterminarli. Non potrai distinguere quelli incantati solo guardandoli, quindi dovrai ucciderli tutti.", enHash = {"8b94f81d","adf8fdab","a9629beb"}}
db[93949] = db[93949] or {}
db[93949]["objectives"] = db[93949]["objectives"] or {it = "Uccidi i Saltacieli a Valanaar finché non avrai eliminato 8 Saltacieli Incantati.", enHash = {"4bd619c8"}}
db[93949] = db[93949] or {}
db[93949]["reward"] = db[93949]["reward"] or {it = "Di certo ci sono altri insetti in giro per Valanaar, ma ogni saltacielo incantato che schiacciamo rende la città un po’ più sicura.", enHash = {"885328cc"}}
db[93958] = db[93958] or {}
db[93958]["title"] = db[93958]["title"] or {it = "Il santuario interno", enHash = {"cea49d70"}}
db[93958] = db[93958] or {}
db[93958]["text"] = db[93958]["text"] or {it = "Le forze di Valennia hanno appena fatto irruzione nel santuario interno. All’inizio i combattimenti erano feroci, ma ora tutto è diventato... inquietantemente silenzioso. Entra e cerca di raggiungere Valennia e i suoi... se ne è rimasto qualcuno.\n\nIo resterò qui a coprirti le spalle.", enHash = {"0bd72b24","3f9b2a30","3d0a025a"}}
db[93958] = db[93958] or {}
db[93958]["objectives"] = db[93958]["objectives"] or {it = "Parla con Valennia Stormfist nel santuario interno del Santuario di Akir.", enHash = {"632a23fc"}}
db[93958] = db[93958] or {}
db[93958]["reward"] = db[93958]["reward"] or {it = "<Valennia sembra gravemente ferita.>", enHash = {"4df34ee0"}}
db[94369] = db[94369] or {}
db[94369]["title"] = db[94369]["title"] or {it = "Il destino di Zephras", enHash = {"10e89c1d"}}
db[94369] = db[94369] or {}
db[94369]["text"] = db[94369]["text"] or {it = "Ansirem mi ha parlato molto dei signori elementali e temo che ora abbiamo buone ragioni per avere paura di Al'Akir: le protezioni che nascondevano Zephras sono cadute. Se il Signore del Vento decidesse di attaccarci, qui nel suo dominio non potremmo difenderci.\n\nL’Alto Anziano Shadowsong deve conoscere il pericolo e, soprattutto, le nostre intenzioni per la missione ad Azeroth. Troveremo il modo di salvare la nostra casa. Lo giuro.", enHash = {"a7bd2a72","c1f00cf0","71f6e71a"}}
db[94369] = db[94369] or {}
db[94369]["objectives"] = db[94369]["objectives"] or {it = "Parla con Talaanis Shadowsong a Valanaar.", enHash = {"71321ddf"}}
db[94369] = db[94369] or {}
db[94369]["reward"] = db[94369]["reward"] or {it = "<Talaanis Shadowsong ascolta attentamente il racconto di ciò che è successo sopra il Santuario di Akir e del piano di Elaadrin di lasciare Zephras.>\n\nDevo rifletterci ancora. Il lato positivo è che ci siamo liberati di Lorthuna e abbiamo privato il culto della sua guida. La nostra casa non è stata invasa e, per dei semidei elementali, potrebbero passare anni, persino decenni, prima che Al’Akir ci degni della sua attenzione.\n\nAbbiamo molto da temere, ma anche molto da festeggiare.", enHash = {"94adbb30","37657e78","6bef3838"}}
db[94413] = db[94413] or {}
db[94413]["title"] = db[94413]["title"] or {it = "Un affronto magico", enHash = {"2509fddd"}}
db[94413] = db[94413] or {}
db[94413]["text"] = db[94413]["text"] or {it = "La recente comparsa delle linee di faglia sulla superficie di Zephras è stata una scoperta fondamentale per il nostro ordine. Ora possiamo accedere in modo più diretto e concreto alle energie che permeano questo luogo, e la nostra comprensione di quella magia è cresciuta enormemente.\n\nI Plasmavento, però, considerano queste manifestazioni ferite della terra da «curare». È un affronto al nostro ordine che non possiamo tollerare.\n\nRaggiungi la linea di faglia nella foresta a sud-ovest e scaccia i Plasmavento che trovi.", enHash = {"7051a43b","77153cc5","73a3af05"}}
db[94413] = db[94413] or {}
db[94413]["objectives"] = db[94413]["objectives"] or {it = "Uccidi 6 Veggenti Novizi dei Plasmavento nelle alture di Shen’dar.", enHash = {"54ea7949"}}
db[94413] = db[94413] or {}
db[94413]["reward"] = db[94413]["reward"] or {it = "A volte faccio fatica a distinguere il cieco fanatismo degli Al’Aketh dall’ostinato rifiuto dei Plasmavento di cambiare.\n\nSe credessero davvero nella guida dei venti, ne seguirebbero la direzione invece di opporvisi.", enHash = {"3f81c8cd","57987f11","be47bd27"}}
db[94485] = db[94485] or {}
db[94485]["title"] = db[94485]["title"] or {it = "Lacrime della Dama", enHash = {"f25697f3"}}
db[94485] = db[94485] or {}
db[94485]["text"] = db[94485]["text"] or {it = "Per salvare i miei compagni nella Tana degli Artigli della Notte mi serviranno ingredienti per un impiastro. Il primo e più importante è un muschio sottile chiamato Lacrima della Dama. Di solito cresce alla base degli alberi di Shadowgale.\n\nSecerne una sostanza appiccicosa che agisce da antisettico ed è perfetta per medicare le ferite aperte. Ho raccolto quel poco che riuscivo a raggiungere, ma nella foresta ce n’è altro.\n\nVai, e fai presto. Ne servirà molto se i feriti che ho lasciato sono ancora vivi.", enHash = {"4c9796e9","49285b4d","e3f625f9"}}
db[94485] = db[94485] or {}
db[94485]["objectives"] = db[94485]["objectives"] or {it = "Raccogli 8 Muschi Lacrima della Dama.", enHash = {"abb27aba"}}
db[94485] = db[94485] or {}
db[94485]["progress"] = db[94485]["progress"] or {it = "Hai trovato la Lacrima della Dama?", enHash = {"67a57bf9"}}
db[94486] = db[94486] or {}
db[94486]["title"] = db[94486]["title"] or {it = "Piume per le medicazioni", enHash = {"78bdae3e"}}
db[94486] = db[94486] or {}
db[94486]["text"] = db[94486]["text"] or {it = "L’altro ingrediente per l’impiastro sono le piume degli strillatori che vagano nella foresta di Shadowgale. Da giovani hanno piume isolanti, ideali da mettere sopra il muschio. Impediranno alla linfa antisettica di seccarsi e offriranno almeno un po’ di protezione dalle intemperie.\n\nAttenzione: gli strillatori sono normalmente docili, ma ultimamente sono diventati molto aggressivi. I loro grandi artigli possono sventrarti facilmente se non stai in guardia.", enHash = {"69c613ba","49b86a42","bf9ea4ec"}}
db[94486] = db[94486] or {}
db[94486]["objectives"] = db[94486]["objectives"] or {it = "Raccogli 20 piume dagli Strillatori di Shadowgale nella Foresta di Shadowgale.", enHash = {"4151e15e"}}
db[94486] = db[94486] or {}
db[94486]["progress"] = db[94486]["progress"] or {it = "Mi addolora chiederti di uccidere i giovani strillatori, ma con la loro crescente aggressività è la scelta migliore. Possiamo affrontare solo un certo numero di emergenze alla volta.", enHash = {"90f6ea64"}}
db[94486] = db[94486] or {}
db[94486]["reward"] = db[94486]["reward"] or {it = "Grazie. Userò ogni piuma, perché il loro sacrificio non sia vano.", enHash = {"2755b97c"}}
db[94487] = db[94487] or {}
db[94487]["title"] = db[94487]["title"] or {it = "Indesiderati e indegni", enHash = {"9ca2d045"}}
db[94487] = db[94487] or {}
db[94487]["text"] = db[94487]["text"] or {it = "I cultisti Al'Aketh ci hanno assaliti senza preavviso, e le loro ragioni restano un mistero. Sapevo che avevano le nuvole nel cervello, ma non avrei mai immaginato che sconvolgessero con tanta brutalità il fragile equilibrio di Zephras. Vai, uccidine quanti più puoi e prendi i cimeli che portano.\n\n<Elegael sputa.>\n\nQuei cultisti maledetti dalla tempesta non meritano di essere chiamati shen'dorei. Le bestie della foresta possono avere i loro corpi. Le loro ceneri non meritano il vento.", enHash = {"6c561072","d82357ee","ed35512e"}}
db[94487] = db[94487] or {}
db[94487]["objectives"] = db[94487]["objectives"] or {it = "Raccogli 10 Cimeli Insanguinati dai Fanti Al'Aketh e dagli Inseguitori della Tempesta Al'Aketh nella Foresta di Shadowgale.", enHash = {"49c514e9"}}
db[94487] = db[94487] or {}
db[94487]["progress"] = db[94487]["progress"] or {it = "Farò pagare al culto ogni goccia di sangue dei druidi versata oggi.", enHash = {"1bbe5f60"}}
db[94487] = db[94487] or {}
db[94487]["reward"] = db[94487]["reward"] or {it = "<Elegael guarda con angoscia i cimeli insanguinati.>\n\nTante giovani vite piene di potenziale sono perdute per sempre. Grazie per averli riportati, $C.\n\nLi custodirò finché potrò consegnarli all’Alto Anziano. Torneranno nella collezione, in attesa che una nuova generazione, forse più degna, raggiunga la maggiore età.", enHash = {"f425c3ca","3e24be1c","2f0d1c70"}}
db[94488] = db[94488] or {}
db[94488]["title"] = db[94488]["title"] or {it = "I legami che ci uniscono", enHash = {"e7f064a8"}}
db[94488] = db[94488] or {}
db[94488]["text"] = db[94488]["text"] or {it = "Non capisco ancora perché i cultisti siano qui, ma tra il sangue versato sento un odore familiare.\n\nUno dei druidi del nostro circolo, Haalien, è scomparso mesi fa. Sembra che abbia deciso di unirsi ai cultisti.\n\nMostragli cosa succede a chi versa il sangue dei propri fratelli! Prendi la sua testa e portamela.", enHash = {"8d56784f","1e03441b","7c9ecd6f"}}
db[94488] = db[94488] or {}
db[94488]["objectives"] = db[94488]["objectives"] or {it = "Uccidi il Comandante Haalien e porta la sua testa a Elegael Thornpaw nella Foresta di Shadowgale.", enHash = {"b1db6ca4"}}
db[94488] = db[94488] or {}
db[94488]["progress"] = db[94488]["progress"] or {it = "Le vite dei nostri fratelli valgono davvero così poco per te, Haalien?", enHash = {"496f5aae"}}
db[94489] = db[94489] or {}
db[94489]["title"] = db[94489]["title"] or {it = "Le ferite del tradimento", enHash = {"6a686bbc"}}
db[94489] = db[94489] or {}
db[94489]["text"] = db[94489]["text"] or {it = "Ho finito gli impiastri. Portali subito ai druidi nella grotta a nord, oltre la radura. So che i miei fratelli sono in condizioni molto peggiori delle mie: probabilmente sono troppo feriti per curarsi da soli. Noi druidi shen’dorei siamo così pochi che ogni vita è preziosa.\n\nPrima che tu vada, ho una richiesta egoista. Il mio compagno, Jorel Windsinger, era in condizioni disperate quando l’ho lasciato. Se è ancora vivo, cura le sue ferite.", enHash = {"838d1a47","2034abc3","1259b259"}}
db[94489] = db[94489] or {}
db[94489]["objectives"] = db[94489]["objectives"] or {it = "Entra nella Tana delle Zanne della Notte, cura 7 druidi e trova Jorel Windsinger nella Foresta di Shadowgale.", enHash = {"1e243658"}}
db[94489] = db[94489] or {}
db[94489]["progress"] = db[94489]["progress"] or {it = "$C! Sei di ritorno. Hai raggiunto i miei fratelli e le mie sorelle? Hai trovato Jorel?", enHash = {"7c317034"}}
db[94489] = db[94489] or {}
db[94489]["reward"] = db[94489]["reward"] or {it = "<Il volto di Elegael impallidisce mentre racconti il destino di Jorel e le condizioni degli altri druidi.>\n\nNo... no! È molto peggio di quanto avessi...\n\n<Elegael soffoca un singhiozzo, serra i denti e lascia uscire un ringhio di dolore.>\n\nPagheranno. Pagheranno TUTTI. Chiunque si allei con gli Al’Aketh subirà la mia ira! Lo giuro.", enHash = {"b868808f","79ec044f","2a941839"}}
db[94490] = db[94490] or {}
db[94490]["title"] = db[94490]["title"] or {it = "La missiva strappata", enHash = {"71e11d92"}}
db[94490] = db[94490] or {}
db[94490]["text"] = db[94490]["text"] or {it = "<Dietro uno dei bracciali di Haalien trovi un biglietto, leggermente strappato e macchiato di sangue durante lo scontro. Sembra contenere informazioni utili sulle ragioni dell’attacco del culto alla tana dei druidi. Elegael vorrà leggerlo.>", enHash = {"ed19c43a"}}
db[94490] = db[94490] or {}
db[94490]["objectives"] = db[94490]["objectives"] or {it = "Porta la Missiva Strappata a Elegael Thornpaw nella Foresta di Shadowgale.", enHash = {"cf8a7d52"}}
db[94490] = db[94490] or {}
db[94490]["reward"] = db[94490]["reward"] or {it = "Erano qui per il pilone? Ma a quale scopo? Non eravamo noi il vero obiettivo dell’attacco?\n\n<Elegael si interrompe, tremando di rabbia mentre legge.>\n\nHanno ucciso i miei perché eravamo d’intralcio! Farò a pezzi ogni cultista con le mie zanne. Nessuno uscirà vivo da qui.\n\nVai, presto! Se gli ordini venivano davvero da Valanaar, probabilmente vi si nasconde un traditore. Porta la missiva a Lotheluum e raccontagli ciò che è successo.", enHash = {"f2c73a43","41774507","cec829dd"}}
db[94491] = db[94491] or {}
db[94491]["title"] = db[94491]["title"] or {it = "Il destino della tana", enHash = {"d7e5d11a"}}
db[94491] = db[94491] or {}
db[94491]["text"] = db[94491]["text"] or {it = "Sembra che a Valanaar si nasconda qualcuno che passa informazioni al culto. È evidente che non sono in condizioni di viaggiare, ma Lotheluum deve sapere cosa è successo qui.\n\nDeve anche conoscere il destino di chi non è più tra noi. Grazie al tuo aiuto credo che possiamo gestire il resto, anche se il danno è ormai fatto.\n\nVai in fretta, $N. Spero che un giorno le nostre strade si incrocino di nuovo. Fino ad allora, ho dei cultisti da uccidere.", enHash = {"abf97b11","a38a74e9","b58fe295"}}
db[94491] = db[94491] or {}
db[94491]["objectives"] = db[94491]["objectives"] or {it = "Consegna la missiva a Lotheluum a Valanaar e raccontagli ciò che è accaduto.", enHash = {"1eeb400e"}}
db[94568] = db[94568] or {}
db[94568]["title"] = db[94568]["title"] or {it = "I veri piani del culto", enHash = {"c4bfbba3"}}
db[94568] = db[94568] or {}
db[94568]["text"] = db[94568]["text"] or {it = "Il disertore temeva chiaramente i piani del culto, tanto da abbandonarlo e cercare il nostro aiuto. È davvero una disgrazia che sia morto portando i suoi segreti nella tomba.\n\nDobbiamo discuterne ancora per decidere i prossimi passi.", enHash = {"9af922d8","d0aa63cc","ed0a6076","b4536d67","76a50b5d","93050807"}}
db[94568] = db[94568] or {}
db[94568]["objectives"] = db[94568]["objectives"] or {it = "Parla con Talaanis Shadowsong e assisti alla conversazione.", enHash = {"a614d49f"}}
db[94568] = db[94568] or {}
db[94568]["progress"] = db[94568]["progress"] or {it = "Quel disertore ha rischiato tutto per sfuggire al culto e portarci questo cristallo...", enHash = {"af53e326"}}
db[94568] = db[94568] or {}
db[94568]["reward"] = db[94568]["reward"] or {it = "Potremmo mandare i guardiani ad affrontare direttamente il culto, ma in campo aperto non avremmo buone possibilità.\n\nCi serve un approccio diverso.", enHash = {"fe912eeb","55df978d","097f1c23"}}
db[94946] = db[94946] or {}
db[94946]["title"] = db[94946]["title"] or {it = "La città magica di Dalaran", enHash = {"48a03882"}}
db[94946] = db[94946] or {}
db[94946]["text"] = db[94946]["text"] or {it = "Volevo essere il primo di noi a mettere piede su Azeroth, ma i recenti eventi con il culto hanno cambiato i miei piani. Resterò a Valanaar ancora per un po’. Non preoccuparti: uno dei nostri maghi ti accoglierà al tuo arrivo a Dalaran. Ti invito a esplorare Azeroth mentre sistemiamo le cose qui. Ti chiameremo quando avremo bisogno di te.\n\nQuando vuoi partire, raggiungi il molo appena fuori da questa dimora e sali sulla nave volante.", enHash = {"7ca41e7c","a67e96c4","2a2e6b5a"}}
db[94946] = db[94946] or {}
db[94946]["objectives"] = db[94946]["objectives"] or {it = "Prendi la nave volante da Zephras a Dalaran e parla con Danaaris Stargale al tuo arrivo.", enHash = {"f1d33198"}}
db[94946] = db[94946] or {}
db[94946]["reward"] = db[94946]["reward"] or {it = "Ah, sei arrivato. Magnifico. Ci vorrà un po’ per stabilirci qui: nel frattempo puoi esplorare la città. Cerca però di non allontanarti troppo dalla sua sicurezza.\n\nPer quanto questa terra sembri idilliaca, uscire da Dalaran senza preparazione ed esperienza può essere estremamente pericoloso.", enHash = {"de66ff73","63bab9bb","41872ae5"}}
db[95349] = db[95349] or {}
db[95349]["title"] = db[95349]["title"] or {it = "Il Circolo della Terra", enHash = {"df8ebf0c"}}
db[95349] = db[95349] or {}
db[95349]["text"] = db[95349]["text"] or {it = "I recenti eventi con il culto hanno ritardato il mio viaggio verso Azeroth: dovrò restare a Valanaar ancora per un po’. Tu e alcuni altri Plasmavento sarete invece la nostra avanguardia. Alaana Stormwalker vi accoglierà al vostro arrivo a Mulgore. Ti invito a esplorare Azeroth mentre concludiamo le nostre faccende qui. Vi raggiungeremo presto.\n\nQuando vuoi partire, raggiungi il molo appena fuori da questa dimora e sali sulla nave volante.\n\nBanu-Alah, $N.", enHash = {"eb6755f9","07617443","af919ddf","34317691","a87ad4dd","68208187"}}
db[95349] = db[95349] or {}
db[95349]["objectives"] = db[95349]["objectives"] or {it = "Prendi la nave volante da Zephras a Mulgore e parla con Alaana Stormwalker al tuo arrivo.", enHash = {"c43c4c32"}}
db[95349] = db[95349] or {}
db[95349]["reward"] = db[95349]["reward"] or {it = "Altri avventurieri da Zephras, vedo. Magnifico. I venti ci sono favorevoli! Ci vorrà un po’ per stabilirci qui: nel frattempo puoi esplorare questa nuova terra.\n\nAzeroth è un mondo emozionante, ma anche pericoloso. Faresti bene a prepararti alla nuova avventura prendendo confidenza con le terre vicine.", enHash = {"df782719","bd26ef7d","16f04693"}}
db[98512] = db[98512] or {}
db[98512]["title"] = db[98512]["title"] or {it = "Assassini Al’Aketh", enHash = {"37d94501"}}
db[98512] = db[98512] or {}
db[98512]["text"] = db[98512]["text"] or {it = "Ehi, tu. Abbassati e non fare rumore. Non siamo soli.\n\nPattugliavo il confine quando ho notato diversi Al'Aketh aggirarsi attorno alla casa sulla collina a nord. Non so cosa stiano facendo, ma non può essere nulla di buono.\n\nSe vuoi renderti utile, entra ed eliminali. Io aspetterò qui e ti coprirò le spalle.", enHash = {"b057d16d","2072c90d","21d74c39"}}
db[98512] = db[98512] or {}
db[98512]["objectives"] = db[98512]["objectives"] or {it = "Uccidi 10 Assassini Al'Aketh nelle alture di Shen'dar.", enHash = {"412a73d2"}}
db[98512] = db[98512] or {}
db[98512]["progress"] = db[98512]["progress"] or {it = "Chissà cosa cercano.", enHash = {"9c613cd9"}}
db[98512] = db[98512] or {}
db[98512]["reward"] = db[98512]["reward"] or {it = "Sono lieto che tu sia tornato. Quegli Al’Aketh sembravano assassini spietati.\n\nGrazie per l’aiuto: lo includerò nel mio rapporto quando tornerò a Valanaar.", enHash = {"30e951f4","db4be584","9805d89a"}}
db[92850] = db[92850] or {}
db[92850]["text#2"] = db[92850]["text#2"] or {it = "Mi sento già molto meglio. Conosco un po’ le arti arcane e Valanaar è vicina: posso farcela da solo. Più importante della mia sicurezza, però, è il pericolo di questi strillatori, che hanno nidificato così vicino alla città. Se vuoi farmi un favore, torna dentro e prendi la testa di quella bestia!\n\nQuando avrai finito, mi troverai a Valanaar. Devo riferire al Magistro Supremo ciò che è successo e lo stato della mia missione.", enHash = {"16a1fa91","d1a25893","ded9eebd"}}
db[92850] = db[92850] or {}
db[92850]["objectives#2"] = db[92850]["objectives#2"] or {it = "Uccidi la Matriarca degli Strillatori nella loro tana e porta la sua testa a Fillion Flamebreeze a Valanaar.", enHash = {"af8f1394"}}
