db[92460] = db[92460] or {}
db[92460]["text#screenshot17"] = {it = "Guardati: occhi pieni di entusiasmo e tanta voglia di avventura! Qui al villaggio di Thendal abbiamo bisogno di tutto l’aiuto possibile, e il tuo arrivo è più che benvenuto. Immagino che l’emozione per ciò che ti aspetta ti renda nervoso. Dopotutto, si raggiunge la maggiore età una sola volta nella vita.\n\nVai a cercare il capo del villaggio, Rorian the Dayseeker, all’ingresso dell’albero del Grande Padre, poco a ovest di qui. Ti aiuterà a iniziare il tuo viaggio.", enHash = "5b41f9e9"}
